// Hands Background Service Worker
// Brain of the extension: manages conversation, CDP, keepalive, and all agent actions

export {}

// Allow the extension icon click to open the side panel
chrome.sidePanel.setPanelBehavior({ openPanelOnActionClick: true }).catch((error) => console.error(error));

// Fallback for Opera: Manually force open the side panel on click
chrome.action.onClicked.addListener((tab) => {
  if (tab.windowId) {
    chrome.sidePanel.open({ windowId: tab.windowId }).catch(console.error);
  }
});
