function safeParseJSON(text: string): any {
  try { return JSON.parse(text); } catch(e) {}
  
  let inString = false;
  let escape = false;
  let cleanJson = "";
  
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (escape) {
      escape = false;
      cleanJson += char;
      continue;
    }
    if (char === '\\') {
      escape = true;
      cleanJson += char;
      continue;
    }
    if (char === '"') {
      inString = !inString;
      cleanJson += char;
      continue;
    }
    if (inString) {
      if (char === '\n') cleanJson += '\\n';
      else if (char === '\r') cleanJson += '\\r';
      else if (char === '\t') cleanJson += '\\t';
      else cleanJson += char;
    } else {
      cleanJson += char;
    }
  }
  
  try { return JSON.parse(cleanJson); } catch(e) { return null; }
}

