async function cleanPageLabels() {
  try {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true })
    if (tab?.id) {
      await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: () => document.querySelectorAll(".hands-label").forEach((el) => el.remove())
      })
    }
  } catch {}
}

async function runAgentLoop(
  userMessage: string,
  images: string[] | undefined,
  sendChunk: (chunk: string) => void,
  sendStatus: (status: string) => void,
  sendDone: (fullReply: string) => void,
  sendScreenshot: (b64: string) => void
) {
  state.cancelRequested = false;
  state.abortController = new AbortController();

  // Get current tab context
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true })
  const tabContext = tab ? `[Context: Active Tab is "${tab.title}" at ${tab.url}]\n` : ""

  // Add user message to history with tab context
  let finalContent: ContentPart[] | string = tabContext + userMessage;
  if (images && images.length > 0) {
    const contentArr: ContentPart[] = [{ type: "text", text: finalContent }];
    for (const img of images) {
      contentArr.push({ type: "image_url", image_url: { url: img } });
    }
    state.messages.push({ role: "user", content: contentArr, timestamp: new Date().toISOString() })
  } else {
    state.messages.push({ role: "user", content: finalContent, timestamp: new Date().toISOString() })
  }
  
  state.isProcessing = true
  let loopCount = 0
  const MAX_LOOPS = 99999

  while (loopCount < MAX_LOOPS) {
    if (state.cancelRequested) {
      sendDone("Agent stopped by user.")
      break
    }

    loopCount++

    let fullReply = ""
    let fullReasoning = ""
    
    // Call Together AI
    try {
      const payloadMessages = state.messages.map(m => {
        const res: any = { role: m.role, content: m.content };
        if (m.reasoning_details) res.reasoning = m.reasoning_details;
        return res;
      })

      await callLLMAI(
        payloadMessages,
        (chunk) => sendChunk(chunk),
        (full, reasoning) => { fullReply = full; fullReasoning = reasoning }
      )
    } catch (e: any) {
      fullReply = e.message || "Failed to communicate with AI provider"
      chrome.storage.local.set({
        streamBuffer: fullReply,
        streamDone: true,
        streamStatus: "Failed",
        streamScreenshot: null
      })
      chrome.runtime.sendMessage({ type: "AGENT_ERROR", error: fullReply });
      state.isProcessing = false;
      return; // break the loop entirely
    }

    // Add assistant reply to history
    state.messages.push({ role: "assistant", content: fullReply, reasoning_details: fullReasoning || undefined, timestamp: new Date().toISOString() })

    // Check for a tool call
    const toolCall = parseToolCall(fullReply)

    if (!toolCall) {
      // No tool call, we're done, clean up labels
      await cleanPageLabels()
      persistState()
      state.isProcessing = false
      sendDone(fullReply)
      return
    }

    // Execute the tool
    sendStatus(`Executing: ${toolCall.action}...`)

    try {
      let { result, screenshotBase64 } = await executeTool(toolCall.action, toolCall.params)

      const isError = result.toLowerCase().includes("error:") || result.toLowerCase().includes("failed to") || result.toLowerCase().includes("could not");
      if (isError && state.lastFailedAction === toolCall.action) {
         state.consecutiveFailures = (state.consecutiveFailures || 0) + 1;
      } else if (isError) {
         state.consecutiveFailures = 1;
         state.lastFailedAction = toolCall.action;
      } else {
         state.consecutiveFailures = 0;
         state.lastFailedAction = "";
      }

      if (state.consecutiveFailures >= 3) {
          result = result + "\n\n[SYSTEM: Tool failed 3 times in a row. You MUST output text asking the user for help. Do not guess anymore.]";
      }

      if (screenshotBase64) {
        sendScreenshot(screenshotBase64)
        // Feed screenshot back to model as vision message
        state.messages.push({
          role: "user",
          content: [
            { type: "text", text: `Tool result for ${toolCall.action}: ${result}. Here is the screenshot:` },
            { type: "image_url", image_url: { url: `data:image/jpeg;base64,${screenshotBase64}` } }
          ]
        })
      } else {
        // Feed text result back
        state.messages.push({
          role: "user",
          content: `Tool result for ${toolCall.action}: ${result}`
        })
      }
    } catch (e: any) {
      state.messages.push({
        role: "user",
        content: `Tool error for ${toolCall.action}: ${e.message}`
      })
    }
  }

  // Hit loop limit
  await cleanPageLabels()
  state.isProcessing = false
  persistState()
  sendDone("I've reached the maximum number of consecutive actions (150) for a single request to prevent infinite loops. If the task isn't finished, you can ask me to continue.")
}

function parseAndHideActions(text: string): { actions: any[], cleanText: string } {
  const actions: any[] = [];
  let cleanText = text;

  // 1. Remove DSML wrappers if any
  cleanText = cleanText.replace(/<(?:\||ï½œ){1,2}DSML(?:\||ï½œ){1,2}\s+calls>/gi, "");
  cleanText = cleanText.replace(/<\/(?:\||ï½œ){1,2}DSML(?:\||ï½œ){1,2}\s+calls>/gi, "");

  // 2. Remove DSML invoke blocks
  const dsmlInvokeRegex = /<(?:\||ï½œ){1,2}DSML(?:\||ï½œ){1,2}\s+invoke\s+name="([^"]+)">([\s\S]*?)<\/(?:\||ï½œ){1,2}DSML(?:\||ï½œ){1,2}\s+invoke>/gi;
  cleanText = cleanText.replace(dsmlInvokeRegex, (match, action, inner) => {
    const paramsMatch = inner.match(/<(?:\||ï½œ){1,2}DSML(?:\||ï½œ){1,2}\s+parameter\s+name="params"[^>]*>([\s\S]*?)<\/(?:\||ï½œ){1,2}DSML(?:\||ï½œ){1,2}\s+parameter>/i);
    let params = {};
    if (paramsMatch) {
      params = safeParseJSON(paramsMatch[1].trim()) || {};
    }
    actions.push({ action, params });
    return "";
  });

  const partialDsml1 = cleanText.lastIndexOf('<ï½œï½œDSML');
  const partialDsml2 = cleanText.lastIndexOf('<||DSML');
  const maxPartialDsml = Math.max(partialDsml1, partialDsml2);
  if (maxPartialDsml !== -1 && !cleanText.substring(maxPartialDsml).includes('</')) {
    cleanText = cleanText.substring(0, maxPartialDsml);
  }

  // 3. Remove XML blocks
  const xmlRegex = /<tool_use>([\s\S]*?)<\/tool_use>/gi;
  cleanText = cleanText.replace(xmlRegex, (match, inner) => {
    const nameMatch = inner.match(/<name>([^<]+)<\/name>/i);
    const inputMatch = inner.match(/<input>([\s\S]*?)<\/input>/i);
    if (nameMatch && inputMatch) {
      const action = nameMatch[1].trim();
      const params = safeParseJSON(inputMatch[1].trim()) || {};
      actions.push({ action, params });
    }
    return "";
  });

  const partialXml = cleanText.lastIndexOf('<tool_use>');
  if (partialXml !== -1 && !cleanText.includes('</tool_use>', partialXml)) {
    cleanText = cleanText.substring(0, partialXml);
  }

  // 3.5 Remove Alternate XML blocks (<invoke><parameter>)
  // First clear <tool_calls> wrappers
  cleanText = cleanText.replace(/<tool_calls>/gi, "");
  cleanText = cleanText.replace(/<\/tool_calls>/gi, "");
  
  const altXmlRegex = /<invoke\s+name="([^"]+)">([\s\S]*?)<\/invoke>/gi;
  cleanText = cleanText.replace(altXmlRegex, (match, action, inner) => {
    const paramsMatch = inner.match(/<parameter\s+name="params"[^>]*>([\s\S]*?)<\/parameter>/i);
    if (paramsMatch) {
      const params = safeParseJSON(paramsMatch[1].trim()) || {};
      actions.push({ action, params });
    }
    return "";
  });

  const partialInvoke = cleanText.lastIndexOf('<invoke');
  if (partialInvoke !== -1 && !cleanText.includes('</invoke>', partialInvoke)) {
    cleanText = cleanText.substring(0, partialInvoke);
  }

  // 4. Fallback standard JSON parsing
  let start = 0;
  while (true) {
    const openIdx = cleanText.indexOf('{', start);
    if (openIdx === -1) break;

    let balance = 0;
    let endIdx = -1;
    let inString = false;
    let escape = false;

    for (let i = openIdx; i < cleanText.length; i++) {
      const char = cleanText[i];
      if (escape) {
        escape = false;
        continue;
      }
      if (char === '\\') {
        escape = true;
        continue;
      }
      if (char === '"') {
        inString = !inString;
        continue;
      }
      if (!inString) {
        if (char === '{') balance++;
        else if (char === '}') balance--;
        
        if (balance === 0) {
          endIdx = i;
          break;
        }
      }
    }

    if (endIdx !== -1) {
      const possibleJson = cleanText.substring(openIdx, endIdx + 1);
      try {
        const parsed = safeParseJSON(possibleJson);
        if (parsed && typeof parsed === 'object' && (parsed.action || parsed.name || parsed.tool)) {
          actions.push(parsed);
          
          let before = cleanText.slice(0, openIdx);
          let after = cleanText.slice(endIdx + 1);
          
          before = before.replace(/```(?:json)?\s*$/, '');
          after = after.replace(/^\s*```/, '');
          
          // ReAct prefix cleanup if matched
          before = before.replace(/Action:\s*[^\n]+\s*Action\s+Input:\s*$/i, '');
          
          // Hermes <tool_call> cleanup if matched
          before = before.replace(/<tool_call>\s*$/i, '');
          after = after.replace(/^\s*<\/tool_call>/i, '');
          
          cleanText = before + after;
          continue;
        }
      } catch (e) {}
    }
    
    start = openIdx + 1;
  }

  const lastOpen = cleanText.lastIndexOf('{');
  if (lastOpen !== -1) {
    const trailing = cleanText.slice(lastOpen);
    if (!trailing.includes('}')) {
      let before = cleanText.slice(0, lastOpen);
      before = before.replace(/```(?:json)?\s*$/, '');
      cleanText = before;
    }
  }

  return { actions, cleanText: cleanText.trim() };
}

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message.type === "FETCH_USER_INFO") {
    fetch("https://www.googleapis.com/oauth2/v2/userinfo", {
      headers: { Authorization: `Bearer ${message.token}` }
    })
      .then(res => res.json())
      .then(data => sendResponse({ success: true, data }))
      .catch(err => sendResponse({ success: false, error: err.message }));
    return true; // Keep message channel open for async response
  }

  if (message.type === "CREATE_SESSION") {
    fetch(`${message.baseUrl}/api/auth/session`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ googleToken: message.googleToken })
    })
      .then(async (res) => {
        if (!res.ok) {
          const errText = await res.text();
          throw new Error(`Server returned ${res.status}: ${errText}`);
        }
        return res.json();
      })
      .then(data => sendResponse({ success: true, data }))
      .catch(err => sendResponse({ success: false, error: err.message }));
    return true; // Keep message channel open for async response
  }

  if (message.type === "FETCH_TOKENS") {
    fetch(`${message.baseUrl}/api/tokens`, {
      headers: { Authorization: `Bearer ${message.token}` }
    })
      .then(async (res) => {
        if (!res.ok) {
          const errText = await res.text();
          throw new Error(`Server returned ${res.status}: ${errText}`);
        }
        return res.json();
      })
      .then(data => sendResponse({ success: true, data }))
      .catch(err => sendResponse({ success: false, error: err.message }));
    return true; // Keep message channel open for async response
  }

  if (message.type === "APPROVAL_RESPONSE") {
    if (pendingApproval) pendingApproval.resolve(message.approved);
    return;
  }
  
  if (message.type === "RETRY_CHAT") {
    let localBuffer = ""
    chrome.storage.local.set({ streamBuffer: "", streamDone: false, streamStatus: "", streamScreenshot: null, streamActions: [] })

    runAgentLoop(
      "", // No new message, resume loop with current state
      undefined,
      (chunk) => {
        localBuffer += chunk
        const { actions, cleanText } = parseAndHideActions(localBuffer)
        chrome.storage.local.set({ streamBuffer: cleanText, streamActions: actions })
      },
      (status) => {
        chrome.storage.local.set({ streamStatus: status })
      },
      (full) => {
        localBuffer = full
        const { actions, cleanText } = parseAndHideActions(full)
        chrome.storage.local.set({ streamDone: true, streamBuffer: cleanText, streamActions: actions })
      },
      (b64) => {
        chrome.storage.local.set({ streamScreenshot: b64 })
      }
    )
    return;
  }

  if (message.type === "CHAT") {
    const { text, images, chatId, taskId } = message
    if (chatId) state.activeChatId = chatId;
    if (taskId) state.activeTaskId = taskId;

    // In-memory accumulator to avoid race conditions on rapid chunk writes
    let localBuffer = ""
    chrome.storage.local.set({ streamBuffer: "", streamDone: false, streamStatus: "", streamScreenshot: null, streamActions: [] })

    runAgentLoop(
      text,
      images,
      // onChunk: accumulate locally, write full buffer atomically
      (chunk) => {
        localBuffer += chunk
        const { actions, cleanText } = parseAndHideActions(localBuffer)
        chrome.storage.local.set({ streamBuffer: cleanText, streamActions: actions })
      },
      // onStatus
      (status) => {
        chrome.storage.local.set({ streamStatus: status })
      },
      // onDone: write final full reply
      (full) => {
        localBuffer = full
        const { actions, cleanText } = parseAndHideActions(full)
        chrome.storage.local.set({ streamDone: true, streamBuffer: cleanText, streamActions: actions })
      },
      // onScreenshot
      (b64) => {
        chrome.storage.local.set({ streamScreenshot: b64 })
      }
    )

    sendResponse({ ok: true })
    return true
  }

  if (message.type === "STOP") {
    state.cancelRequested = true
    if (state.abortController) {
      state.abortController.abort()
      state.abortController = null
    }
    sendResponse({ ok: true })
    return true
  }

  if (message.type === "LOAD_CHAT") {
    state.cancelRequested = true
    chrome.storage.local.set({ streamBuffer: "", streamDone: true, streamStatus: "" })
    
    // Convert UI ChatMessage (which uses "text") into Backend Message (which uses "content")
    let loadedMsgs = (message.messages || []).map((m: any) => {
      if (m.role === "system") return m;
      let contentArr: any[] = [{ type: "text", text: m.text }];
      if (m.images) {
        for (const img of m.images) {
          contentArr.push({ type: "image_url", image_url: { url: img } });
        }
      }
      return { role: m.role, content: contentArr, timestamp: new Date().toISOString() };
    });

    if (loadedMsgs.length === 0 || loadedMsgs[0].role !== "system") {
      state.messages = [{ role: "system", content: SYSTEM_PROMPT }, ...loadedMsgs];
    } else {
      loadedMsgs[0].content = SYSTEM_PROMPT;
      state.messages = loadedMsgs;
    }
    
    persistState()
    sendResponse({ ok: true })
    return true
  }
  
  if (message.type === "CLEAR_HISTORY") {
    state.cancelRequested = true
    chrome.storage.local.set({ streamBuffer: "", streamDone: true, streamStatus: "" })
    state.messages = [{ role: "system", content: SYSTEM_PROMPT }]
    persistState()
    sendResponse({ ok: true })
    return true
  }

  if (message.type === "SET_MODEL") {
    if (message.modelType === "chat") {
      state.selectedChatModel = message.model
    }
    persistState()
    sendResponse({ ok: true })
    return true
  }

  if (message.type === "GET_STATE") {
    sendResponse({
      selectedChatModel: state.selectedChatModel,
      messageCount: state.messages.length
    })
    return true
  }
})









